import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import{calculate}from'./rail-vintages-2026-10-03.mjs';
const read=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url)));
test('October 3 railway transcription and immutable formulas reproduce',()=>{const a=read('research/2026-10-03/sigma-vintages.json'),b=calculate();assert.deepEqual(a,b);assert.equal(a.rows.length,9);assert.ok(a.reconciliation.every(r=>r.revenueDifference===0&&r.tonMilesDifference===0));assert.equal(a.summaries.directory2009.n,5);assert.equal(a.summaries.directory2010.n,7);assert.ok(a.folds.find(r=>r.year===2007).trendAPE>a.folds.find(r=>r.year===2007).naiveAPE);assert.equal(a.originalReleaseDate,null);assert.equal(a.missing2009Outcome,true);assert.ok(a.rows.every(r=>r.capitalStock===null));});
test('four real outputs remain pending and five gaps are not deliveries',()=>{const b=read('assets/citizen-work.json'),d=b.deliveries.filter(d=>d.executionId==='daily-20261003-root');assert.deepEqual(d.map(x=>x.citizenId).sort(),['memoria','runo','saeon','sigma']);assert.ok(d.every(x=>x.review===null));const f=read('assets/research-frontiers.json');for(const id of ['nullroute','leimma','pharma','vox','cynosure'])for(const l of ['zh','en','ko'])assert.ok(f.citizens[id][l].some(r=>r.observationId===`2026-10-03-gap-${id}`&&!r.publicationId));});
test('four new publications retain trilingual caveats and valid attachments',()=>{for(const id of ['saeon','sigma','runo','memoria']){const n=read(`research/2026-10-03/${id}.json`);for(const l of ['zh','en','ko'])assert.ok(n.title[l]&&n.lead[l]&&n.limitation[l]);for(const a of n.attachments)assert.ok(fs.existsSync(new URL('../'+a.path,import.meta.url)));}});
